			title = "Обзор",
			text = [=[Высокогорье Блеклых Перьев поднимается на юге {link:feralas}Фералас{/link}а, рядом с Высокогорными дебрями. Оно названо в честь диких гипп{link:ogres}огр{/link}ифов, что гнездятся там, от молодых рогокрылов до старых патриархов. Гиппогриф издавна друг ночных эльфов, верный и стойкий, и потому тролли Лагеря {link:camp-mojache}Мохаче{/link} охотятся на этих диких зверей ради силы их духов.]=],
		},
	},
})

Translate("ruRU", "grimtotem-compound", {
	title = "Лагерь Зловещего Тотема",
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Зловещего Тотема — стоянка {link:tauren}таурен{/link}ов {link:grimtotem-clan}Зловещего Тотема{/link} в восточном лесу, к западу от Лагеря {link:camp-mojache}Мохаче{/link}. Его натуралисты, налетчики и шаманы ловят дракончиков-летунов, волшебных драконов {link:feralas}Фералас{/link}а, и держат их взаперти в бамбуковых клетках. Никто не знает, зачем они им нужны. Две ночные эльфийки наблюдают за лагерем с гряды над ним, а {link:horde}Орда{/link} Мохаче, узнав, что Зловещий Тотем здесь, назначила цену за их рога.]=],
		},
	},
})

Translate("ruRU", "lariss-pavilion", {
	title = "Павильон Лорисс",
	sections = {
		{
			title = "Обзор",
			text = [=[Павильон Лорисс — эльфийские руины на востоке {link:feralas}Фералас{/link}а, к северу от Лагеря {link:camp-mojache}Мохаче{/link}. Его старые камни стали убежищем, где живет {link:azj-tordin}Азж'Тордин{/link}, старейшина, бежавший из Эльдре'Таласа от его падшего принца. Он живет там тихо, и от прежней жизни у него мало что осталось, кроме учености.]=],
		},
	},
})

Translate("ruRU", "woodpaw-hills", {
	title = "Холмы Древолапов",
	aliases = { "Логово Древолапов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Холмы Древолапов лежат к югу от Лагеря {link:camp-mojache}Мохаче{/link}, и {link:gnolls}гнолл{/link}ы стаи Древолапов заполнили их стоянками и логовами. Годами их набеги на лагерь были лишь досадной помехой. В последнее время гноллы обезумели. Их собственные планы сражений показывают почему: большая часть их сил обращена на юг, против насекомых Гудящей Бездны, и они проигрывают. Война на два фронта довела их до отчаяния.]=],
		},
	},
})

Translate("ruRU", "the-writhing-deep", {
	title = "Гудящая Бездна",
	sections = {
		{
			title = "Обзор",
			text = [=[Гудящая Бездна — улей на дальнем юго-востоке {link:feralas}Фералас{/link}а. Земля там скручена в курганы и ходы и кишит насекомыми Зукк'аш: жалоносами, осами, рабочими и землероями. Ученые и {link:darnassus}Дарнасса{/link}, и {link:orgrimmar}Оргриммара{/link} называют их силитидами, родней роев {link:silithus}Силитуса{/link}. Своих пленников они заживо запечатывают в коконы из затвердевшей слизи. Исполин среди них, прозванный {link:stinglasher}Жалохлест{/link}ом, бродит по улью, окутанный аурой, какой нет у его меньших сородичей.]=],
		},
	},
})

Translate("ruRU", "shandris-feathermoon", {
	title = "Шандриса Оперенная Луна",
	subtitle = "Генерал армии Часовых",
	found = "Крепость Оперенной Луны, главный двор",
	hint = [=[Найдите генерала Часовых в ее островной крепости у западного берега.]=],
	allegiance = "Часовые · Дарнасс",
	aliases = { "Шандриса", "генерал Оперенная Луна" },
	sections = {
		{
			title = "Обзор",
			text = [=[Шандриса Оперенная Луна — генерал армии Часовых, меч верховной жрицы {link:tyrande-whisperwind}Тиранды Шелест Ветра{/link} и первый солдат {link:night-elves}ночных эльфов{/link}. Она командует не из {link:darnassus}Дарнасса{/link}. Свою ставку она устроила в Крепости Оперенной Луны, на острове у берега {link:feralas}Фералас{/link}а, на южном краю земель, которые ее народ все еще охраняет. Голос ее резок, слов у нее мало, а тех, кто служит ей хорошо, благодарят, награждают и снова отправляют в путь.]=],
		},
		{
			title = "Значение",
			text = [=[{link:sentinels}Часовые{/link} — войско народа, которому в эту эпоху войско вовсе не должно было понадобиться. Со времен {link:third-war}Третьей войны{/link} они сражаются с {link:horde}Ордой{/link} в {link:ashenvale}Ясеневом лесу{/link} и {link:stonetalon-mountains}Когтистых горах{/link}, и Шандриса держит этот рубеж по всему {link:kalimdor}Калимдору{/link}. {link:feralas}Фералас{/link} — ее ответ на более важный вопрос: что останется от дикого мира, когда война кончится? Она пришла на юг, чтобы последние зеленые земли материка не достались Орде, и намерена их удержать.

Предания о ней уходят глубже любой нынешней войны. Рассказывают, что она была ребенком, когда {link:war-of-the-ancients}Война древних{/link} сокрушила ее мир, — сиротой, которую взяла под опеку юная жрица {link:tyrande-whisperwind}Тиранда{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она привела отряд Часовых в {link:feralas}Фералас{/link} и построила {link:feathermoon-stronghold}Крепость Оперенной Луны{/link}.
• Она послала разведчиков в {link:ruins-of-solarsal}Руины Соларсаля{/link}, когда там собрались наги Гребня Ненависти, и поручила войну с {link:naga}нага{/link}ми своему заместителю {link:latronicus-moonspear}Латроникус{/link}у Лунному Копью.
• Она отказалась бросить все свои силы против наг, опасаясь оставить крепость открытой для Орды или для чего-то худшего.
• Она послала весть об улье Зукк'аш в {link:darnassus}Дарнасс{/link}, а список донесения курьера Рашаля — жрице Грацине Силе Духа из Храма Луны.
• Друид {link:quintis-jonespyre}Квинтис Джонспайр{/link} называет ее, вместе с Протекторатом, среди соратников, которых тревожит жадность верховного друида до завтрашнего зерна.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна написанная доныне летопись не говорит, когда Шандриса стала генералом и что она делала в самой Третьей войне. Предания о ее детстве идут из историй Войны древних, а не из ее собственных уст.]=],
		},
	},
	chapters = {
		{
			title = "Теплый камень",
			hint = "Обыщите старые руины на юге острова генерала.",
			text = [=[Шандриса считала {link:ruins-of-solarsal}Руины Соларсаля{/link} пустыми. Когда наги пришли туда во множестве, она сперва приняла это за начало нападения, но уверена не была. Вернувшееся донесение описывало беседку новее самих руин, знаки, которых никто не мог прочесть, и камень, теплый под рукой. Она назвала это тревожным. Что бы ни замышляли наги, теперь она знала: они намерены остаться.]=],
		},
		{
			title = "Против Гребня Ненависти",
			hint = "Откликнитесь на призыв генерала против наг.",
			text = [=[Шандриса взвесила дело, как подобает генералу. Она хотела ударить по {link:naga}нага{/link}м каждым клинком, какой у нее был. Знала она и то, что навлечет на себя опустевшая крепость. В конце концов она поручила дело тому, кто наблюдал за нагами дольше всех, — это {link:latronicus-moonspear}Латроникус{/link}, — а сама не сводила глаз с большой войны.]=],
		},
		{
			title = "Восстание силитидов",
			hint = "Примите благодарность генерала за спасение курьера.",
			text = [=[Когда {link:raschal-the-courier}Рашаль{/link} вернулся живым из Гудящей Бездны, Шандриса сама поблагодарила его спасителей. Затем она сразу обратилась к его донесению. Насекомые, запечатывающие живых эльфов в коконы, — дело не для одной крепости. Она отправила донесение в {link:darnassus}Дарнасс{/link}, а список — жрице, знавшей таких тварей, и попросила Элуну хранить их всех.]=],
		},
	},
	mentions = {
		{ text = "«{link:ruins-of-solarsal}Руины Соларсаля{/link}»" },
		{
			text = [=[«Возвращение в {link:feathermoon-stronghold}Крепость Оперенной Луны{/link}»]=],
		},
		{ text = "«Против Гребня Ненависти»" },
		{ text = "«Встреча героя»" },
		{ text = "«Возвышение силитидов»" },
		{ text = "«Просьба Джонспайра», где она названа среди Протектората" },
	},
	bonds = {
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "ее верховная жрица" },
		{ id = "latronicus-moonspear", name = "Латроникус Лунное Копье", note = "ее заместитель" },
		{ id = "ginro-hearthkindle", name = "Гинро Огонь Очага", note = "искал ее пропавшего курьера" },
		{ id = "quintis-jonespyre", name = "Квинтис Джонспайр", note = "ее соратник по Протекторат" },
		{ id = "raschal-the-courier", name = "курьер Рашаль", note = "ее курьер" },
		{ id = "hadoken-swiftstrider", name = "Хадокен Быстрый Шаг", note = "держит лагерь Орды на востоке" },
	},
})

Translate("ruRU", "latronicus-moonspear", {
	title = "Латроникус Лунное Копье",
	subtitle = "Заместитель командующей Оперенной Луны",
	found = "Крепость Оперенной Луны, рядом с генералом",
	hint = [=[Поговорите с офицером, который стоит подле генерала в Оперенной Луне.]=],
	allegiance = "Часовые · Крепость Оперенной Луны",
	aliases = { "Латроникус", "Латро" },
	sections = {
		{
			title = "Обзор",
			text = [=[Латроникус Лунное Копье — второй по старшинству в Крепости Оперенной Луны и офицер, дольше всех наблюдавший за {link:naga}нага{/link}ми Гребня Ненависти. Это практичный солдат. Он ценит тех, кто доводит дело до конца, без жалоб платит награды из казны крепости и открыто признает, что загадки старых реликвий ему не по силам. С ними он отправляет к своей жене.]=],
		},
		{
			title = "Значение",
			text = [=[Там, где {link:shandris-feathermoon}Шандриса{/link} думает обо всей войне, Латроникус думает об острове. Его поход против наг — малая война сама по себе, война за Остров Сардор и воды вокруг него. Он также настороженно следит за злоупотреблением магией и говорит об эльфах, мнящих себя ее хозяевами, как о рабах собственного голода.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он ведет борьбу с {link:naga}нага{/link}ми Гребня Ненависти на Острове Сардор и Острове Ужаса.
• От своих разведчиков он узнал, что нагами командует знать, и обрек на смерть лорда {link:lord-shalzaru}Шалзару{/link}.
• Он объявил курьера Рашаля пропавшим и отправил искателей к воину {link:ginro-hearthkindle}Гинро{/link} Огню Очага.
• Он хочет, чтобы паутину чародейки Летендрис вынесли из {red:dire-maul}Забытого Города{/red} и пойманную в ней магию можно было отпустить обратно в дикую природу.]=],
		},
	},
	chapters = {
		{
			title = "Знать наг",
			hint = "Сломите власть наг на островах близ Оперенной Луны.",
			text = [=[Латроникус задумал свою войну в двух частях: ослабить наг в числе и в командовании и узнать, что они выкапывают. Сначала пришел черед чешуи. Затем его разведчики назвали жестокого лорда наг, {link:lord-shalzaru}Шалзару{/link}, который извлек странную реликвию из пещеры на Острове Ужаса. Когда Шалзару пал, Латроникус счел, что наги надолго останутся в смятении. Саму же реликвию он прочесть не смог вовсе.]=],
		},
		{
			title = "Реликвия",
			hint = "Отнесите реликвию наг ученой Оперенной Луны.",
			text = [=[Он попросил отнести реликвию его жене Вестии — он называет ее лучшей ученой во всех землях. Ему нужно было знать, что это такое. Нагам, как он подозревал, тоже.]=],
		},
	},
	mentions = {
		{ text = "«Против Гребня Ненависти»" },
		{ text = "«Против лорда {link:lord-shalzaru}Шалзару{/link}»" },
		{ text = "«Доставка реликвии»" },
		{ text = "«Пропавший курьер»" },
		{ text = "«Паутина Летендрис»" },
	},
	bonds = {
		{ id = "shandris-feathermoon", name = "Шандриса Оперенная Луна", note = "его генерал" },
		{ id = "vestia-moonspear", name = "Вестия Лунное Копье", note = "его жена" },
		{ id = "lord-shalzaru", name = "лорд Шалзару", note = "враг" },
		{ id = "ginro-hearthkindle", name = "Гинро Огонь Очага", note = "соратник" },
	},
})

Translate("ruRU", "vestia-moonspear", {
	title = "Вестия Лунное Копье",
	subtitle = "Жрица и ученая Оперенной Луны",
	found = "Крепость Оперенной Луны, среди ее книг",
	hint = [=[Найдите жрицу, которая занимается науками в тихом уголке Оперенной Луны.]=],
