	sections = {
		{
			title = "Обзор",
			text = [=[Вестия Лунное Копье — жрица Элуны и жена офицера {link:latronicus-moonspear}Латроникус{/link}а. Муж называет ее одной из самых сведущих ученых на свете и приносит ей каждую загадку, которую не может решить сам. Величайшая из них — реликвия, отнятая у лорда {link:lord-shalzaru}Шалзару{/link}.]=],
