	},
})

Translate("ruRU", "ginro-hearthkindle", {
	title = "Гинро Огонь Очага",
	subtitle = "Искатель из Оперенной Луны",
	found = "Крепость Оперенной Луны, в его покоях",
	hint = [=[Найдите Часового, который не прекращает искать пропавшего курьера.]=],
	allegiance = "Часовые · Крепость Оперенной Луны",
	aliases = { "Гинро", "Джин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гинро Огонь Очага — солдат Крепости Оперенной Луны, не пожелавший отступиться от друга. Когда курьер {link:raschal-the-courier}Рашаль{/link} пропал на дороге в {link:thalanaar}Таланаар{/link}, Гинро каждый день уходил в дебри искать его и каждый вечер возвращался ни с чем, кроме зубов {link:gnolls}гнолл{/link}ов. Даже когда крепость объявила, что Рашаль потерян, он продолжал искать.]=],
		},
		{
			title = "Значение",
			text = [=[Поиски, которые вел Гинро, открыли самую грозную опасность {link:feralas}Фералас{/link}а. Идя по следу пропавшего курьера, искатели нашли улей Зукк'аш — первый в этих землях знак южных силитидов.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он искал пропавшего друга день за днем, в одиночку.
• Он послал нож курьера друиду {link:quintis-jonespyre}Квинтис{/link}у Джонспайру, чтобы тот прочел его прикосновением, и расплатился, простив карточный долг.
• Он настоял на прямом ударе по стоянкам Древолапов, как только видение друида указало туда.
• Он привел спасителей курьера к генералу Шандрисе Оперенной Луне.]=],
		},
	},
	chapters = {
		{
			title = "Обломки",
			hint = "Обыщите побережье Фераласа в поисках лодки курьера.",
			text = [=[{link:raschal-the-courier}Рашаль{/link} собирался пройти на веслах вдоль берега и пересечь юг {link:feralas}Фералас{/link}а, чтобы держаться подальше от лагеря Орды. Его лодку нашли затонувшей и разодранной, с гербом крепости на борту. В иле под ней лежал его нож. Что-то в воде едва не переломило лодку надвое.]=],
		},
		{
			title = "Тайна ножа",
			hint = "Узнайте, что помнит нож курьера.",
			text = [=[{link:quintis-jonespyre}Квинтис{/link} взял нож в руки и увидел, как {link:raschal-the-courier}Рашаль{/link} несет два тюка вглубь суши, встречает Древолапов и возвращается к лодке в страхе. Ничто из того, что могли сделать {link:gnolls}гнолл{/link}ы, его не пугало. Его испугало нечто иное, и так сильно, что он не заметил, как позади него поднимается вода. Тогда Гинро понял, что ищет не тело.]=],
		},
		{
			title = "Освобождение из улья",
			hint = "Пройдите по следу курьера до конца.",
			text = [=[Тюки висели на дереве в стоянках Древолапов. Внутри была записка: {link:raschal-the-courier}Рашаль{/link} обнаружил насекомых к югу от {link:gnolls}гнолл{/link}ов и пошел взглянуть на них сам. В Гудящей Бездне его нашли запечатанным в кокон, оглушенным, но живым. Гинро сказал его спасителям, что в нем они всегда найдут друга.]=],
		},
	},
