			title = "Деяния",
			text = [=[• Он приказал одного за другим быстро сразить вожаков Древолапов, чтобы ввергнуть {link:gnolls}гнолл{/link}ов в хаос.
• Он послал искателей за планами сражений гноллов.
• Он приказал проредить Зукк'аш в Гудящей Бездне, а величайшего их зверя, {link:stinglasher}Жалохлест{/link}а, вскрыть для изучения.
• Он отправил донесение лагеря о насекомых гоблину Зилзибину Драмлору в {link:orgrimmar}Оргриммар{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Война с Древолапами",
			hint = "Отбросьте гноллов, совершающих набеги на Лагерь Мохаче.",
			text = [=[Древолапы всегда нападали на лагерь, и {link:horde}Орда{/link} всегда их отбивала. В последнее время набеги стали свирепыми и беспрестанными, словно {link:gnolls}гнолл{/link}ам больше некуда было идти. Хадокен задумал сломить их одним резким ударом. На время это удалось. Это же заставило его задуматься, что довело их до такого неистовства.]=],
		},
		{
			title = "Планы сражений",
			hint = "Найдите планы сражений гноллов в их южных стоянках.",
			text = [=[Карта {link:gnolls}гнолл{/link}ов рассказала все. Большинство стрел на ней указывало на юг, прочь от Лагеря {link:camp-mojache}Мохаче{/link}, а рядом с рисунком {link:ogres}огр{/link}омного насекомого тянулись ряды зарубок — их мертвые. Древолапы вели войну на два фронта, и проигрывали они не ту, что шла против Орды.]=],
		},
		{
			title = "Зукк'аш",
			hint = "Доставьте донесение лагеря о насекомых в Оргриммар.",
			text = [=[Хадокен не заботился о том, умеют ли насекомые думать. Они гнали {link:gnolls}гнолл{/link}ов на его лагерь и потому были его врагом. Когда его находки достигли {link:orgrimmar}Оргриммар{/link}а, гоблин Зилзибин Драмлор дал насекомым их истинное имя — силитиды — и предупредил, что {link:horde}Орда{/link} слишком долго не обращала на них внимания.]=],
		},
	},
	mentions = {
		{ text = "«Война с Древолапами»" },
		{ text = "«Альфа-удар»" },
		{ text = "«Расследование о Древолапах»" },
		{ text = "«Планы сражения»" },
		{ text = "«Нашествие Зукк'аш»" },
		{ text = "«{link:stinglasher}Жалохлест{/link}»" },
		{ text = "«Донесение о Зукк'аш»" },
	},
	bonds = {
		{ id = "stinglasher", name = "Жалохлест", note = "зверь, которого он хотел изучить" },
		{ id = "rok-orhan", name = "Рок Орхан", note = "сражается с ограми рядом с ним" },
		{ id = "shandris-feathermoon", name = "Шандриса Оперенная Луна", note = "держит крепость Альянса на западе" },
	},
})

