	},
})

Translate("ruRU", "witch-doctor-uzer-i", {
	title = "Знахарь Узер'и",
	subtitle = "Знахарь Лагеря Мохаче",
	found = "Лагерь Мохаче",
	hint = [=[Поговорите с троллем-знахарем из Лагеря Мохаче, которому нужен особый сосуд.]=],
	allegiance = "Орда · Лагерь Мохаче",
	aliases = { "Узер'и" },
	sections = {
		{
			title = "Обзор",
			text = [=[Знахарь Узер'и — тролль из Лагеря {link:camp-mojache}Мохаче{/link} и мастер древнего и тревожащего искусства. Он знает, что такое муисек — дух, который создание оставляет после себя, когда гибнет насильственной смертью. Такой дух, учит он, может ускользнуть, искать мести и даже вернуться в обличье большего зверя. Узер'и нашел способ этому помешать. Создание, уменьшенное и пойманное в миг смерти, не может отпустить свой муисек, а пойманным муисеком можно воспользоваться.]=],
		},
		{
			title = "Значение",
			text = [=[Труд, который ведет Узер'и, — оружие, нацеленное на ночных эльфов. Он выбирает создания по их связи с {link:night-elves}калдореи{/link}: это дикие совухи, некогда любимцы Элуны; гипп{link:ogres}огр{/link}ифы, их верные скакуны; волшебные драконы, их союзники; древни, их защитники; и горные великаны, которые спустились со своих вершин, чтобы помочь им против {link:burning-legion}Пылающего Легиона{/link}. Их сила, говорит он, должна послужить и Орде.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он выменял у чернокнижника {link:neeru-fireblade}Ниру{/link} Огненного Клинка из {link:orgrimmar}Оргриммара{/link} травы, нужные для сосуда, за высушенную голову {link:dwarves}дворф{/link}а.
• Он посылал охотников до самых {link:the-hinterlands}Внутренних земель{/link}, чтобы поймать муисек диких совухов.
• Он запечатал пойманных духов в оружие.]=],
		},
	},
	chapters = {
		{
			title = "Сосуд для муисека",
			hint = "Принесите знахарю травы, которых он ждет из Оргриммара.",
			text = [=[{link:neeru-fireblade}Ниру Огненный Клинок{/link} приготовил травы и остался доволен головой, которую за них получил. Узер'и тут же совершил над сосудом свой обряд. Первое его испытание ждало далеко, среди совухов Внутренних земель, и оно должно было проверить и обряд, и охотника, несшего сосуд.]=],
		},
		{
			title = "Оружие духа",
			hint = "Соберите для знахаря все нужные ему духи.",
			text = [=[Гипп{link:ogres}огр{/link}иф, волшебный дракон, древень и горный великан: один за другим союзники ночных эльфов были уменьшены и пойманы. Расщепленным деревом, минералами, жилами и обломками металла Узер'и навеки привязал их духов к оружию, которое выковал.]=],
		},
	},
	mentions = {
		{ text = "«Странная просьба»" },
		{ text = "«Возвращение к знахарю Узер'и»" },
		{ text = "«Испытание сосуда»" },
		{ text = "«Муисек гипп{link:ogres}огр{/link}ифа»" },
		{ text = "«Муисек волшебного дракончика»" },
		{ text = "«Муисек древня»" },
		{ text = "«Муисек горного великана»" },
		{ text = "«Природные материалы»" },
		{ text = "«Оружие духа»" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Ниру Огненный Клинок", note = "меняется с ним травами" },
	},
})

