Translate("ruRU", "falfindel-waywarder", {
	title = "Фалфиндель Страж Путей",
	subtitle = "Друид Таланаара",
	found = "Таланаар, на восточном краю Фераласа",
	hint = [=[Найдите друида, который хранит путевую станцию на восточном краю леса.]=],
	allegiance = "Круг Кенария · Таланаар",
	aliases = { "Фалфиндель" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фалфиндель Страж Путей — друид ночных эльфов, хранящий {link:thalanaar}Таланаар{/link}, одинокую путевую станцию там, где леса {link:feralas}Фералас{/link}а встречаются с каньонами {link:thousand-needles}Тысячи Игл{/link}. Хранители Когтистых гор зовут его великим и мудрым. Говорят, что он умеет призывать великих духов леса на помощь израненным землям.]=],
		},
		{
			title = "Значение",
			text = [=[Со своего тихого поста Фалфиндель присматривает не только за {link:feralas}Фералас{/link}ом. Его забота простирается в {link:the-barrens}Степи{/link}, где осквернено место упокоения полубога-вепря Агамаггана, и на север до самых {link:stonetalon-mountains}Когтистых гор{/link}, чей хранитель умолял его о помощи.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он изучает, что осквернило место упокоения полубога на юге Степей.
