			text = [=[Посылка из Оперенной Луны пришла поздно и из рук незнакомца. Фалфиндель сразу догадался, что с обычным курьером, Рашалем, что-то случилось. У него были и свои подозрения: Древолапы в последнее время стали беспокойны, их растревожило что-то на юге.]=],
		},
	},
	mentions = {
		{ text = "«Дневник Хмурня»" },
		{ text = "«{link:charlga-razorflank}Старуха из Лабиринтов{/link}»" },
